def solve(payload):
    import math
    length = payload["length_m"]
    loads, probes = payload["loads"], payload["probes_m"]
    if length <= 0 or any(not 0 <= load["x_m"] <= length for load in loads) or any(not 0 <= x <= length for x in probes):
        return {"error": "invalid_geometry"}
    right = math.fsum(load["force_n"] * load["x_m"] for load in loads) / length
    left = math.fsum(load["force_n"] for load in loads) - right
    moments = [left * x - math.fsum(load["force_n"] * max(0, x - load["x_m"]) for load in loads) for x in probes]
    return {"left_reaction_n": left, "right_reaction_n": right, "moments_nm": moments}

